B=P/'benchmark-v2';B.mkdir(exist_ok=False)
for obj in [baseq,basek]: obj['benchmark_version']='v2-expanded'
baseq['questions']=questions;basek['answers']=answers
for name,data in [('questions.json',baseq),('answer-key.json',basek)]: (B/name).write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
(B/'question-bank.md').write_text('# Unmatched expanded fixed bank v2\n\n'+ '\n\n'.join(f"## {q['id']}\n\n{q['question']}\n\n**Expected:** {a['expected_answer']}\n\n**Source:** {'; '.join(a['source_refs'])}" for q,a in zip(questions,answers))+'\n')
(B/'scope-map.json').write_text(json.dumps({'benchmark':'v2-expanded','policy':'Each required_facts item maps to actual question clauses. Contextual_background is explicitly not a scoring requirement. No unrelated source completeness caps.','questions':[{'id':q['id'],'asked_clauses':q['question'],'required_answer_facts':a['required_facts'],'contextual_key_background':a['contextual_background'],'source_refs':a['source_refs']} for q,a in zip(questions,answers)]},ensure_ascii=False,indent=2)+'\n')
(B/'additions.json').write_text(json.dumps(additions,ensure_ascii=False,indent=2)+'\n')
(B/'input-manifest.json').write_text(json.dumps({'original_preservation':questions[:20]==json.loads((P/'benchmark-v1/questions.json').read_text())['questions'] and answers[:20]==json.loads((P/'benchmark-v1/answer-key.json').read_text())['answers'],'hashes':{n:hashlib.sha256((B/n).read_bytes()).hexdigest() for n in ['questions.json','answer-key.json','scope-map.json','question-bank.md','additions.json']}},indent=2)+'\n')
print(len(questions),'expanded questions; fixed originals preserved')
